    anomaly_flag     BOOLEAN      NOT NULL DEFAULT false,
    liters           NUMERIC(12,2) NOT NULL DEFAULT 0,
    cost             NUMERIC(14,2) NOT NULL DEFAULT 0,
    odometer_km      NUMERIC(14,2) NOT NULL DEFAULT 0,
