    vat_number                    VARCHAR(60)  NOT NULL DEFAULT '',
    commercial_registration_no    VARCHAR(60)  NOT NULL DEFAULT '',
    country_code                  VARCHAR(8)   NOT NULL DEFAULT 'SA',
