);

CREATE TABLE IF NOT EXISTS fleet_tms_cold_chain_policies (
            id BIGINT NOT NULL GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
            company_id BIGINT NOT NULL,
            branch_id BIGINT NULL,
